mapper.select:
SELECT h.id, h.customer_id, h.old_owner_id, ou.display_name AS old_owner_name,
       h.new_owner_id, nu.display_name AS new_owner_name,
       h.changed_by, cu.display_name AS changed_by_name,
       h.reason, h.approval_ref, h.effective_at, h.created_at
FROM crm_customer_owner_history h
LEFT JOIN sys_user ou ON ou.tenant_id = h.tenant_id AND ou.id = h.old_owner_id
LEFT JOIN sys_user nu ON nu.tenant_id = h.tenant_id AND nu.id = h.new_owner_id
LEFT JOIN sys_user cu ON cu.tenant_id = h.tenant_id AND cu.id = h.changed_by
WHERE h.tenant_id = #{tenantId} AND h.customer_id = #{customerId}


    AND COALESCE(h.effective_at, h.created_at) <= #{cursorOccurredAt}


    AND (COALESCE(h.effective_at, h.created_at) < #{cursorOccurredAt}
         OR (COALESCE(h.effective_at, h.created_at) = #{cursorOccurredAt} AND h.id < #{cursorSourceId}))


    AND COALESCE(h.effective_at, h.created_at) < #{cursorOccurredAt}



ORDER BY COALESCE(h.effective_at, h.created_at) DESC, h.id DESC
LIMIT #{limit}

mapper.sql:
WHERE h.tenant_id = #{tenantId}
  AND c.deleted = 0



    AND (c.owner_staff_id = #{selfId}

      OR c.team_id IN #{t}
    )


    AND c.owner_staff_id = #{selfId}

  AND 1 = 0


  AND h.customer_id = #{customerId}


  AND (h.old_owner_id = #{ownerId} OR h.new_owner_id = #{ownerId})


  AND (c.customer_no LIKE CONCAT('%', #{keyword}, '%')
    OR c.display_name LIKE CONCAT('%', #{keyword}, '%')
    OR c.nickname LIKE CONCAT('%', #{keyword}, '%'))
